    var dlg = box.closest('.dialog'), opts = dlg && dlg.querySelector('.dtfix-opts'), right = dlg && dlg.querySelector('.dtfix-right');
    if (!dlg || !opts || !right || !dlg.offsetWidth) return;
    var sc = dlg.getBoundingClientRect().width / dlg.offsetWidth || 1, d = dlg.getBoundingClientRect(), o = opts.getBoundingClientRect(), r = right.getBoundingClientRect();
    var top = Math.round((o.top - d.top) / sc - dlg.clientTop), h = Math.round((Math.max(r.bottom, o.bottom) - o.top) / sc);
    if (h > 0) { box.style.setProperty('--dtfix-mt', top + 'px'); box.style.setProperty('--dtfix-mh', h + 'px'); }
    var rb = dlg.querySelector('.dtfix-reset'), bt = [].filter.call(dlg.querySelectorAll('.actions button'), function (b) { return b.offsetWidth > 0 && !b.classList.contains('dtfix-reset'); });
    if (!rb) return;
