    var a = bt[0].getBoundingClientRect(), z = bt[bt.length - 1].getBoundingClientRect(), cx, cy = (Math.min(a.top, z.top) + Math.max(a.bottom, z.bottom)) / 2;
    if (bt.length > 1) cx = (a.right + z.left) / 2; else cx = a.right + 14 * sc + rb.offsetWidth * sc / 2;
