  try{if(!localStorage.location){const m={GB:'EU-London',RU:'RU-Russia',TR:'TK-Turkey',BR:'BR-Brazil',US:'US-Atlanta',CN:'CN-China',JP:'JP-Tokyo',AU:'SG-Singapore'};localStorage.location=m[guessCountry()]||'EU-London'}}catch(e){}
  // ---- network: the old master server (m.agar.io) is gone; its three requests are answered from today's master ----
