  const rc=document.createElement('script');rc.dataset.a16='1';rc.src='https://www.google.com/recaptcha/api.js?render=6LcEt74UAAAAAIc_T6dWpsRufGCvvau5Fd7_G1tY';rc.async=true;document.body.appendChild(rc);
  if(/[?&]debug\b/.test(location.search))S.verbose=true;
