        if(LF!==f)return rej(new Error('closed'));
        try{const w=f.contentWindow,A=w&&w.agarApp&&w.agarApp.API;if(A&&A.coreWasLoaded&&typeof A.openShop==='function'&&w.core&&typeof w.core.proxyMobileData==='function')return res(w)}catch(e){}
        if(Date.now()-t0>40000)return rej(new Error('The shop did not load'));
