      AC.dbg('shop: catalog '+(cfgOk?'loaded':'NOT reported, continuing'));
      if(cfgOk)await sleep(250);
      else cfg.late=()=>{if(LFw===w&&LFmode==='bridge'){AC.dbg('shop: catalog loaded late, login replayed');restate(w)}};
